import { inject } from "vue";
import type { InjectionKey, MaybeRefOrGetter } from "vue";

/** Image thumbnails generated by vc-module-image-tools. */
export type VcImageThumbnailsType = {
  enabled?: boolean;
  /** Show the original image when a thumbnail fails to load. */
  originalFallbackEnabled?: boolean;
  /** File name suffix per `VcImage` `sizeSuffix`, without the leading underscore. */
  suffixes?: { sm: string; md: string; lg: string };
};

export type VcNotificationOptionsType = {
  text?: string;
  html?: string;
  group?: string;
  /** In milliseconds. */
  duration?: number;
  closeButton?: boolean;
  single?: boolean;
  singleGroup?: boolean;
  singleInGroup?: boolean;
};

/** Shows a toast and returns a function that closes it. */
export type VcNotifyType = (options: VcNotificationOptionsType) => () => void;

export type VcNotificationsType = {
  info: VcNotifyType;
  success: VcNotifyType;
  warning: VcNotifyType;
  error: VcNotifyType;
};

/**
 * Services the app hands to the kit: `app.use(uiKit, options)`. Every option is optional: without it
 * `VcImage` shows `src` as is and `VcCopyText` copies without a toast.
 */
export interface IUiKitOptions {
  image?: {
    thumbnails?: MaybeRefOrGetter<VcImageThumbnailsType>;
    /**
     * The image `VcImage` shows when `src` is empty or fails to load, site-wide: a URL, or a file name in the
     * app's images. An instance's `fallbackSrc` wins. Default: ui-kit's `no-image.svg`.
     */
    fallbackSrc?: MaybeRefOrGetter<string>;
    /**
     * Turns a bare file name (`"basket.jpg"`) passed to `VcImage` (`src`, `fallbackSrc`) or `VcShape` (`img`)
     * into a URL, for example one of the app's images. Without it the file name is used as is.
     */
    resolveFileName?: (fileName: string) => string;
  };
  notifications?: VcNotificationsType;
}

export const uiKitOptionsKey: InjectionKey<IUiKitOptions> = Symbol("vc-ui-kit-options");

export function useUiKitOptions(): IUiKitOptions {
  return inject(uiKitOptionsKey, {});
}
